// Regenerate boot.min.ts from boot.ts: node libs/bridge/build-boot.ts
// Same scheme as the runtime's build-loader.ts: the source is serialized with Function#toString (Node's type
// stripping leaves whitespace where annotations were; esbuild's minifier normalizes it) and minified. The lean tail
// test fails when the generated file is stale.
import { writeFile } from "node:fs/promises";
import { transform } from "esbuild";
import { boot } from "./boot.ts";

/** Minified inline lean boot (`(…)()`, browser globals only). */
export const minifiedBoot = async (): Promise<string> => (await transform("(" + boot + ")()", { minify: true, target: "es2020" })).code.trim();

if (import.meta.url === new URL(process.argv[1]!, "file://").href) {
  const code = await minifiedBoot();
  const file = new URL("./boot.min.ts", import.meta.url);
  // Written prettier-clean (repo format gate); prettier is a root devDependency.
  const prettier = await import("prettier");
  const text = "// Generated by build-boot.ts from boot.ts. Do not edit.\n" + "export const BOOT = " + JSON.stringify(code) + ";\n";
  const path = file.pathname;
  await writeFile(file, await prettier.format(text, { ...(await prettier.resolveConfig(path)), filepath: path }));
  console.log(code.length + " chars");
}
